using Godot;

public partial class TransformationMatchOperations
{
    private static T Add<T>(Node parent,T child) where T:Node{parent.AddChild(child);return child;}
    private static void Text(Node parent,string text){var label=Add(parent,new Label {Text=text});label.AddThemeColorOverride("font_color",new Color("80dcca"));}
    private static Button Button(Node parent,string text,System.Action action){var button=Add(parent,new Button {Text=text,CustomMinimumSize=new Vector2(0,28)});button.Pressed+=action;return button;}
    public Resource? key(PopupPanel owner){var document=owner.Get("workspace").AsGodotObject().Get("session").AsGodotObject().Get("document").AsGodotObject();var item=document.Call("component",owner.Get("component_id")).As<Resource>();return item?.Call("key_for_id",owner.Get("key_id")).As<Resource>();}
    public void open(PopupPanel owner)
    {
        var workspace=owner.Get("workspace").As<Control>();workspace.Call("style_popup",owner);var column=Add(owner,new VBoxContainer {CustomMinimumSize=new Vector2(760,520)});Text(column,"MATCH POINTS · click a feature on the left, then its partner on the right");var surface=owner.Call("_create_surface").As<Control>();surface.Set("host",owner);surface.CustomMinimumSize=new Vector2(740,300);column.AddChild(surface);owner.Set("surface",surface);Text(column,"INTERMEDIATE · live canvas composite");Add(column,new TextureRect {CustomMinimumSize=new Vector2(400,150),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered,Texture=workspace.Get("animation_renderer").AsGodotObject().Call("texture").As<Texture2D>()});var row=Add(column,new HBoxContainer());Text(row,"Preview");var slider=Add(row,new HSlider {MinValue=0,MaxValue=1,Step=.001,Value=.5,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});var session=workspace.Get("session").AsGodotObject();var item=session.Get("document").AsGodotObject().Call("component",owner.Get("component_id")).As<Resource>();var keys=item.Call("sorted_keys").AsGodotArray();int index=keys.IndexOf(Variant.From(key(owner)));if(index<0||index+1>=keys.Count){owner.QueueFree();return;}double start=keys[index].AsGodotObject().Get("time").AsDouble(),end=keys[index+1].AsGodotObject().Get("time").AsDouble();slider.ValueChanged+=value=>workspace.Call("seek",Mathf.Lerp(start,end,value));Button(row,"Reset automatic",()=>{var current=key(owner);if(current==null)return;session.Call("begin");current.Set("points_a",System.Array.Empty<Vector2>());current.Set("points_b",System.Array.Empty<Vector2>());current.Set("mode","Auto Morph");session.Call("commit","Reset automatic morph");surface.Set("pending",default(Variant));surface.Set("selected_pair",-1);surface.QueueRedraw();});Button(row,"Unpair",()=>{var current=key(owner);int selected=surface.Get("selected_pair").AsInt32();if(current!=null&&selected>=0&&selected<current.Get("points_a").AsVector2Array().Length){surface.Set("pending",current.Get("points_a").AsVector2Array()[selected]);session.Call("begin");Remove(current,selected);session.Call("commit","Unpair correction point");surface.Set("selected_pair",-1);surface.QueueRedraw();}});var overlays=Add(row,new CheckButton {Text="Overlays",ButtonPressed=true});overlays.Toggled+=value=>{owner.Set("overlays",value);surface.QueueRedraw();};Button(row,"Done",()=>owner.Hide());owner.PopupHide+=()=>{if(surface.Get("drag").AsInt32()>=0)session.Call("cancel");owner.QueueFree();};workspace.Call("seek",Mathf.Lerp(start,end,.5));owner.PopupCentered(new Vector2I(790,560));
    }
}
